use quince_core::{ring::RingVec,types::Trade};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"period",min:2.,max:10000.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_bollinger_width",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:usize,v:RingVec}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{Ok(Box::new(I{p:x[0]as usize,v:RingVec::new(x[0]as usize)}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{self.v.push(t.price);if self.v.len()!=self.p{return None}let m=self.v.iter().sum::<f64>()/self.p as f64;let s=(self.v.iter().map(|x|(x-m)*(x-m)).sum::<f64>()/self.p as f64).sqrt();Some(if m==0.{0.}else{4.*s/m.abs()})}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;use quince_core::types::Side;fn t(p:f64)->Trade{Trade{price:p,qty:1.,time:Utc::now(),side:Side::Buy,trade_id:1}}#[test]fn width(){let mut i=create(&[2.]).unwrap();i.on_trade(&t(10.));assert!(i.on_trade(&t(12.)).unwrap()>0.);}}
